package com.example.systemblock;
import android.app.*;
import android.content.*;
import android.os.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Controlled endpoint checks. Runtime fixtures are generated by CI, never real provider keys. */
final class VpnDeviceChecks {
 private final Instrumentation test;private final Bundle args;private final Context context;
 VpnDeviceChecks(Instrumentation test,Bundle args){this.test=test;this.args=args;context=test.getTargetContext();}
 void run()throws Exception{
  String file=args.getString("vpn_profile"),protocol=args.getString("protocol"),ip=args.getString("server_ip");
  String config=new String(OpenProfile.read(new FileInputStream(new File(context.getExternalFilesDir(null),file)),OpenProfile.LIMIT),StandardCharsets.UTF_8);
  VpnProfiles store=new VpnProfiles(context);List<VpnProfiles.Profile> original=store.load();VpnProfiles.Profile profile=new VpnProfiles.Profile(protocol,config);profile.name="Controlled test endpoint";
  File credentials=new File(context.getExternalFilesDir(null),"test-auth.txt");if(credentials.exists()){List<String> lines=java.nio.file.Files.readAllLines(credentials.toPath());if(lines.size()>=2){profile.user=lines.get(0);profile.password=lines.get(1);}}
  if(Boolean.parseBoolean(args.getString("bad_auth","false")))profile.password="deliberately-invalid-test-password";
  List<VpnProfiles.Profile> profiles=new ArrayList<>(original);profiles.add(profile);store.save(profiles);
  if(!store.find(profile.id).config.equals(config))throw new AssertionError("Encrypted profile round trip failed");
  byte[] encrypted=java.nio.file.Files.readAllBytes(new File(context.getNoBackupFilesDir(),"vpn-profiles.aes").toPath());if(new String(encrypted,StandardCharsets.ISO_8859_1).contains(config))throw new AssertionError("Plaintext profile on disk");
  android.content.SharedPreferences settings=context.getSharedPreferences("settings",0);String previous=settings.getString("vpn_profile","");boolean priorBlocking=settings.getBoolean("block_domains",true);
  settings.edit().putString("vpn_profile",profile.id).putBoolean("block_domains",true).commit();
  try{
   context.startActivity(new Intent(context,Dashboard.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
   context.startForegroundService(new Intent(context,BlockVpn.class));
   long until=SystemClock.elapsedRealtime()+90000;boolean connected=false;
   while(SystemClock.elapsedRealtime()<until){NativeSession session=BlockVpn.activeSession;connected=session!=null&&session.connectedSince>0;if(connected)break;if(Boolean.parseBoolean(args.getString("bad_auth","false"))&&BlockVpn.status.contains("AUTH FAILED"))break;if(Boolean.parseBoolean(args.getString("bad_cert","false"))&&BlockVpn.status.contains("CERT"))break;Thread.sleep(250);}
   if(Boolean.parseBoolean(args.getString("bad_auth","false"))||Boolean.parseBoolean(args.getString("bad_cert","false"))){if(connected)throw new AssertionError("Invalid credentials/certificate connected");if(!BlockVpn.running)throw new AssertionError("Failure removed fail-closed VPN");return;}
   if(!connected)throw new AssertionError("No authenticated connection: "+BlockVpn.status);
   runProbe(ip,true);
   NativeSession session=BlockVpn.activeSession;long started=session.connectedSince;settings.edit().putBoolean("block_domains",false).commit();runProbe(ip,false);
   if(session!=BlockVpn.activeSession||session.connectedSince!=started)throw new AssertionError("Blocking toggle restarted VPN");
   if(session.bytes(true)<=0||session.bytes(false)<=0)throw new AssertionError("No actual forwarded byte counters");
   // Real socket reopen on current network. Wi-Fi/mobile handover needs a phone.
   session.networkChanged();until=SystemClock.elapsedRealtime()+45000;while(session.connectedSince==0&&SystemClock.elapsedRealtime()<until)Thread.sleep(250);
   if(session.connectedSince==0)throw new AssertionError("Reconnect did not authenticate");runProbe(ip,false);
  }finally{
   context.startService(new Intent(context,BlockVpn.class).setAction("stop"));long until=SystemClock.elapsedRealtime()+20000;while(!BlockVpn.status.startsWith("Stopped")&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);
   if(!BlockVpn.status.startsWith("Stopped"))throw new AssertionError("VPN stop did not terminate");
   settings.edit().putString("vpn_profile",previous).putBoolean("block_domains",priorBlocking).commit();store.save(original);
  }
 }
 private void runProbe(String server,boolean blocking)throws Exception{
  shell("rm -f /sdcard/Android/data/com.obskyra.dnsprobe/files/result.txt");
  shell("am start -W -n com.obskyra.dnsprobe/com.example.dnsprobe.DnsProbe --es remote_ip "+server+" --ez blocking "+blocking);
  String report="";long until=SystemClock.elapsedRealtime()+60000;while(SystemClock.elapsedRealtime()<until){report=shell("cat /sdcard/Android/data/com.obskyra.dnsprobe/files/result.txt");if(report.contains("PASS:")||report.contains("FAIL:"))break;Thread.sleep(100);}
  if(!report.contains("PASS:")||report.contains("FAIL:"))throw new AssertionError(report);
 }
 private String shell(String command)throws Exception{try(ParcelFileDescriptor fd=test.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){return new String(OpenProfile.read(in,65536),StandardCharsets.UTF_8);}}
}
